        firstMap.clear();
        secondMap.clear();

        List<Map.Entry<String, String>> list = new ArrayList<>(firstMap.entrySet());
        Collections.sort(list, Comparator.comparing(Map.Entry::getValue));

        System.out.println(testMethod().isEmpty());  // Output: false
    }

